-- Add every bullet fact from the supplied antiquity-focused Lily collection.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (929, $$Трехактная структура: Абсолютно все современные коммерческие фильмы (от «Мстителей» до «Титаника») пишутся по правилам «Поэтики» Аристотеля [elementy.ru]. Он первым доказал, что у истории должны быть жесткие завязка, кульминация и развязка.$$),
  (930, $$Понятие катарсиса: Термин, введенный Аристотелем для описания душевного очищения через страх и сострадание, является главной целью любого современного драматического кино или театрального спектакля.$$),
  (931, $$«Бог из машины» (Deus ex machina): Античный прием, когда запутанный сюжет разрешается внезапным вмешательством высшей силы (в греческом театре актера-бога опускали на сцену с помощью крана). Сегодня этот термин используют критики для описания ленивых сценаристов, спасающих героев в последний момент без логических причин.$$),
  (932, $$Разделение на жанры: Наша привычка делить стриминговые платформы (Netflix, Кинопоиск) на категории «комедия» и «драма/трагедия» — это прямое наследие античной жанровой системы, где эти направления были строго разделены.$$),
  (933, $$Эффект ненадежного рассказчика: Популярный прием в современных психологических триллерах (когда рассказчику нельзя верить) впервые в истории литературы применил Гомер в «Одиссее»: Одиссей сам рассказывает о своих безумных приключениях у циклопов и сирен царю Алкиною, и слушатель подсознательно понимает, что герой может приукрашивать события.$$),
  (934, $$Хор в искусстве: Роль древнегреческого хора, который комментировал действия главных героев, сегодня выполняют закадровый голос рассказчика, саундтреки или посты вымышленных блогеров в современных сериалах.$$),
  (935, $$Четвертая стена: Прием «разрушения четвертой стены» (когда Дэдпул или Фрэнк Андервуд обращаются напрямую к зрителю) зародился в комедиях Аристофана (V в. до н.э.), где актеры в рамках «парабазы» выходили из образа и общались с публикой на злободневные темы.$$),
  (936, $$Сатира как политическое оружие: Современные вечерние шоу (политический юмор вроде The Daily Show или Вечерний Ургант) используют методы сатиры, изобретенные Лукианом и Ювеналом, которые высмеивали пороки римских императоров и патрициев.$$),
  (937, $$Мета-повествование: Книги и фильмы, которые осознают себя как художественное произведение (например, «Адаптация» или романы Пелевина), базируются на приемах Овидия в «Метаморфозах», где автор постоянно прерывает сюжет, чтобы поиграть с читателем.$$),
  (938, $$Клиффхэнгеры (обрывание сюжета на самом интересном): Традиция заканчивать серию сериала на интригующем моменте восходит к структуре поэмы Аполлония Родосского «Аргонавтика», который делил свитки ровно на моментах смертельной опасности для Ясона.$$),
  (939, $$Игры на выживание (Голодные игры): Сьюзен Коллинз официально подтвердила, что сюжет «Голодных игр» — это прямая адаптация мифа о Тесее и Минотавре, описанного в античной литературе, где Афины должны были посылать юношей и девушек на съедение чудовищу в лабиринт.$$),
  (940, $$Архетип Супергероя: Образ современного супергероя (Супермен, Геракл Marvel, Тор) со всеми его атрибутами (сверхсила, трагическая уязвимость, великая миссия) полностью списан с образа Геракла, зафиксированного в трагедиях Еврипида и Сенеки.$$),
  (941, $$Космическая программа «Аполлон»: НАСА назвало свою величайшую лунную программу «Apollo» в честь греческого бога искусств и света, опираясь на классические гимны Гомера, где Аполлон описывается как бог, способный достигать любых пределов.$$),
  (942, $$Романтическое фэнтези: Концепт любви человека и чудовища/невидимого существа («Красавица и Чудовище», «Сумерки») — это буквальный пересказ повести о Амуре и Психее, включенной римским писателем Апулеем в его роман «Метаморфозы, или Золотой осел».$$),
  (943, $$Комиксы и суперзлодеи: Образы безумных тиранов с трагическим прошлым (вроде Таноса) строятся по канонам римского историка Тацита, который в «Анналах» создал глубокие психологические портреты императоров Нерона и Тиберия, превратив их в эталоны литературных злодеев.$$),
  (944, $$Образ Франкенштейна: Мэри Шелли дала своей книге подзаголовок «Современный Прометей». Образ безумного создателя, который страдает от своего же творения, полностью списан с трагедии Эсхила «Прикованный Прометей».$$),
  (945, $$Путешествие героя (Мономиф): Знаменитая концепция Джозефа Кэмпбелла «Тысячеликий герой», по которой Джордж Лукас создал «Звездные войны», целиком выведена из анализа «Одиссеи» Гомера и «Энеиды» Вергилия.$$),
  (946, $$Сюжет «Короля Льва»: История Симбы, которому является призрак отца, призывающий отомстить дяде-предателю, пришла в Disney через Шекспира («Гамлет»), который, в свою очередь, полностью скопировал эту фабулу из трагедии Софокла «Электра» (где Орест мстит за отца Агамемнона).$$),
  (947, $$Сюжет «Ромео и Джульетты»: История несчастных влюбленных из враждующих семей — это не выдумка Шекспира, а точный пересказ истории Пирама и Тисбы из IV книги «Метаморфоз» Овидия.$$),
  (948, $$Потерянный рай (Атлантида): Вся современная приключенческая фантастика о поисках утерянных высокотехнологичных цивилизаций (от Индианы Джонса до «Аватара») базируется на двух коротких диалогах Платона — «Тимей» и «Критий», где впервые в литературе была описана Атлантида.$$),
  (949, $$Эдипов комплекс: Главный термин психоанализа Зигмунда Фрейда получил свое название напрямую от трагедии Софокла «Царь Эдип», где главный герой по трагической ошибке судьбы убивает отца и женится на матери.$$),
  (950, $$Понятие платонической любви: Выражение, означающее духовную любовь без физического влечения, пришло из трактата Платона «Пир», где философ обсуждает разные ступени восхождения души к истинной красоте.$$),
  (951, $$Нарциссизм: Термин, обозначающий болезненное самолюбование, пришел из поэмы Овидия «Метаморфозы», где описана история прекрасного юноши Нарцисса, который влюбился в собственное отражение в воде и умер от тоски.$$),
  (952, $$«О времена, о нравы!» (O tempora, o mores!): Популярный афоризм, используемый писателями и публицистами при критике современной молодежи, — это дословная цитата из Первой речи против Катилины великого римского оратора Цицерона (I в. до н.э.).$$),
  (953, $$«Поэтами не становятся, поэтами рождаются»: Эта крылатая фраза восходит к трактату Цицерона «В защиту поэта Архия», где он впервые сформулировал концепцию божественного дара (вдохновения), предвосхитив эпоху романтизма.$$),
  (954, $$«Панический страх»: Прилагательное «панический» вошло в мировые языки из греческой мифологической литературы (в частности, из «Гимнов Пану»), где описывалось, как бог лесов Пан мог издавать крик, повергающий армии в безотчетный ужас.$$),
  (955, $$«Гомерический хохот»: Выражение, означающее неудержимый, громкий смех, пришло из I книги «Илиады» Гомера, где описывается, как боги на Олимпе смеялись над хромым богом-кузнецом Гефестом.$$),
  (956, $$«Муза» как источник вдохновения: Наша привычка называть творческое вдохновение «музой» восходит к поэмам Гесиода «Теогония» (VIII в. до н.э.), где автор детально структурировал и назвал по именам всех 9 муз, закрепив за ними виды искусств.$$),
  (957, $$«Золотая середина»: Концепция идеального баланса в жизни пришла из II книги «Од» Горация (Aurea mediocritas), который призывал избегать как нищеты, так и разрушающей душу роскоши.$$),
  (958, $$«Счастливы часов не наблюдают»: Знаменитая фраза Грибоедова из «Горя от ума» является парафразом строчки римского комедиографа Плавта из пьесы «Амфитрион»: «Для влюбленных вечность — лишь один час».$$),
  (959, $$Деление на главы/книги: Наша привычка делить толстые романы на «книги» и «главы» зародилась в Александрийской библиотеке в III веке до н.э. Филологи (например, Зенодот Эфесский) при переписывании «Илиады» и «Одиссеи» искусственно разделили каждую поэму на 24 части по количеству букв греческого алфавита для удобства чтения.$$),
  (960, $$Литературная критика: Сама профессия литературного критика и редактора была изобретена в античности. Первым профессиональным критиком считается Аристофан Византийский, который ввел систему знаков препинания и ударений при анализе поэтических текстов.$$),
  (961, $$Жанр биографии: Популярный сегодня нон-фикшн формат ЖЗЛ (Жизнь замечательных людей) целиком скопирован с «Сравнительных жизнеописаний» Плутарха (I в. н.э.), который придумал сопоставлять биографии великих греков и римлян для выявления их моральных качеств.$$),
  (962, $$Эпистолярный роман: Жанр романа в письмах («Страдания молодого Вертера» Гёте, «Бедные люди» Достоевского) развился из сборников «Писем» Плиния Младшего, который превратил обычную дружескую переписку в самостоятельный высокохудожественный литературный жанр.$$),
  (963, $$Жанр романа-путешествия: Все приключенческие романы (от «Вокруг света за 80 дней» до современных тревелогов) выросли из жанра периегезы — путевых заметок древности, эталоном которых стало «Описание Эллады» Павсания (II в. н.э.).$$),
  (964, $$Психологический автопортрет: Жанр интимного дневника и личной исповеди начался с книги римского императора-философа Марка Аврелия «К самому себе» (или «Размышления»). Он писал её в военных походах исключительно для самоанализа, создав первый в истории образец внутренней экзистенциальной прозы.$$),
  (965, $$Понятие плагиата: Слово plagium в Риме означало кражу или продажу в рабство свободного человека. Римский поэт Марциал в своих эпиграммах впервые применил это слово метафорически, обозвав «плагиатором» вора, который украл и выдал за свои его стихи, буквально «угнав его детей-произведений в рабство».$$),
  (966, $$Формат басни: Наша школьная программа с баснями Крылова или Лафонтена полностью базируется на текстах греческого раба Эзопа (VI в. до н.э.). Все сюжеты про Лису и Виноград, Волка и Ягненка — это пересказы эзоповских текстов.$$),
  (967, $$Идея Энциклопедии: Структура сбора всех знаний мира в алфавитном или тематическом порядке была изобретена Плинием Старшим в его 37-томной «Естественной истории», которая служила главным справочником человечества вплоть до Нового времени.$$),
  (968, $$Поэтическое бессмертие (Памятник): Идея о том, что поэт живет вечно в своих стихах («Я памятник себе воздвиг нерукотворный...» Пушкина, Державина, Горация), пошла из знаменитой Оды XXX Горация (Exegi monumentum).$$),
  (969, $$Стоицизм в психотерапии: Современное направление когнитивно-поведенческой терапии (КПТ) целиком основано на трудах римских философов-стоиков — Сенеки («Нравственные письма к Луцилию») и Эпиктета. Их мысль о том, что «человека ранят не вещи, а его отношение к ним», является главным тезисом КПТ.$$),
  (970, $$Диалектика и формат дебатов: Наша система ведения научных дискуссий и судебных прений построена на «Диалогах» Платона, где Сократ с помощью системы наводящих вопросов (майевтики) заставлял оппонента самого обнаружить логическое противоречие в своих словах.$$),
  (971, $$Утопическое мышление: Все социальные проекты идеальных государств (от Томаса Мора до марксизма) выросли из трактата Платона «Государство», где впервые в литературе была предложена модель общества, разделенного на касты философов, воинов и ремесленников с отменой частной собственности.$$),
  (972, $$Понятие гуманизма: Концепция ценности человеческой личности развилась из филологических трудов Цицерона, который ввел термин Humanitas, изучая греческую литературу и доказывая, что чтение «очеловечивает» дикие нравы.$$),
  (973, $$Эпикурейство: Наша бытовая привычка называть любителя изысканной еды и комфорта «эпикурейцем» восходит к искаженному пониманию писем и трактатов философа Эпикура, который на самом деле проповедовал умеренность и избавление от страха смерти как залог счастья.$$),
  (974, $$Идея космополитизма: Термин «гражданин мира» впервые зафиксирован в античной литературе киников: когда Диогена Синопского спросили, откуда он, он ответил: Kosmopolites (гражданин Вселенной), заложив основы глобалистского мышления.$$),
  (975, $$Скептицизм: Философская позиция сомнения в любых догмах, необходимая современным ученым, была детально описана римским автором Секстом Эмпириком в «Пирроновых положениях».$$),
  (976, $$Концепция Эвдемонии: Идея Аристотеля из «Никомаховой этики» о том, что высшее благо человека — это не мимолетное удовольствие (гедонизм), а раскрытие своего внутреннего потенциала и жизнь в согласии с разумом (эвдемония), является базой современной позитивной психологии.$$),
  (977, $$Понятие Альтруизма: Философское обоснование бескорыстной помощи ближнему было выведено Цицероном в трактате «Об обязанностях», который на протяжении веков являлся главной книгой по светской этике в Европе.$$),
  (978, $$Memento mori (Помни о смерти): Литературный концепт осознания конечности жизни для острой оценки текущего момента развился из «Утешений» Сенеки и стихов Марка Аврелия, став важным элементом современной экзистенциальной психологии.$$),
  (979, $$Приемы черного пиара: Все современные политические предвыборные технологии и методы очернения соперников используют приемы Цицерона из его речей «Филиппики» против Марка Антония, где он виртуозно сочетал разбор политических ошибок врага с высмеиванием его личной жизни.$$),
  (980, $$Жанр Памфлета: Острая политическая публицистика началась с романа «Сатирикон» Петрония Арбитра (арбитра изящества при дворе Нерона), который в гротескной форме описал пошлость и бездуховность нуворишей (богатых вольноотпущенников) Римской империи.$$),
  (981, $$Искусство судебной речи: Структура выступления современных адвокатов в суде (вступление, изложение фактов, опровержение доводов стороны обвинения, эмоциональный финал) до сих пор строится по учебнику риторики Квинтилиана «Обучение оратора» (I в. н.э.).$$),
  (982, $$Политический лозунг «Хлеба и зрелищ!»: Главная формула популизма, используемая для описания обществ потребления, — это прямая цитата из Сатиры X Ювенала (Panem et circenses), который упрекал римский народ в том, что они променяли свои политические свободы на бесплатную раздачу зерна и цирковые игры.$$),
  (983, $$Жанр инвективы: Жанр прямой, яростной обличительной речи или статьи (современный «дисс» в поп-культуре) развился из стихотворных инвектив поэт Катулла (I в. до н.э.), который жестко атаковал в своих стихах Юлия Цезаря и его приближенных.$$),
  (984, $$Риторический вопрос: Популярная фигура речи, не требующая ответа, а лишь усиливающая эмоции, была кодифицирована и введена в ораторскую практику Цицероном ( знаменитое: «Доколе же ты, Катилина, будешь злоупотреблять нашим терпением?»).$$),
  (985, $$Концепция Истории как «учительницы жизни»: Афоризм Historia magistra vitae принадлежит Цицерону (трактат «Об ораторе»). Она определила развитие всей мировой исторической прозы как инструмента воспитания граждан.$$),
  (986, $$Понятие тирании: Литературный образ безумного, подозрительного правителя, который уничтожает лучших граждан из страха за свой трон, был детально описан Геродотом в его «Истории» (рассказ о тиране Периандре), создав базу для политической драмы.$$),
  (987, $$Судебный прецедент защиты свободы слова: Первым в истории манифестом в защиту свободы слова и печати стала речь Джона Мильтона «Ареопагитика» (XVII в.), которая по своей структуре и названию является прямым подражанием речи афинского оратора Исократа «Ареопагитик» (IV в. до н.э.).$$),
  (988, $$Жанр утопического романа-путешествия: «Путешествия Гулливера» Джонатана Свифта построены по лекалам пародии Лукиана Самосатского «Правдивая история» (II в. н.э.), где впервые в литературе описывались полеты на Луну, войны космических кораблей и встреча с разумными пауками.$$),
  (989, $$Структура любовного стихотворения: Наша европейская традиция писать стихи о неразделенной любви, страдании, ревности и обожествлении возлюбленной началась с поэтессы Сапфо (VI в. до н.э.). Её стихотворение «Мне кажется точным богом...» цитируется и копируется поэтами уже 2500 лет.$$),
  (990, $$Метафора «Любовь — это война»: Популярный в литературе концепт завоевания сердца женщины как штурма крепости был детально разработан римским поэтом Овидием в его элегиях и поэме «Наука любви» (Militat omnis amans — «Каждый влюбленный — солдат»).$$),
  (991, $$Жанр оды: Традиция писать торжественные стихи в честь правителей, побед или исторических событий (оды Ломоносова, Державина) целиком скопирована с «Триумфальных од» греческого поэта Пиндара (V в. до н.э.).$$),
  (992, $$Анакреонтика: Жанр легкой, жизнерадостной поэзии, воспевающей вино, любовь и беззаботную жизнь (которую обожал юный Пушкин), пошел от стихов древнегреческого лирика Анакреонта.$$),
  (993, $$Образ роковой женщины (Femme fatale): Первым глубоким литературным исследованием психологии разрушительной, безумной женской страсти, толкающей на преступления, стала трагедия Еврипида «Медея». Её образ лег в основу сотен драм Нового времени.$$),
  (994, $$Концепт «Ненавижу и люблю» (Odi et amo): Главная формула психологической амбивалентности чувств в литературе принадлежит римскому поэту Катуллу (Стихотворение 85). Две строчки: «Я и люблю, и люблю ненавидеть. — Зачем же? — не знаю. Чувствую это в себе, крест свой несу и казнюсь» заложили основу психологической лирики.$$),
  (995, $$Жанр Пасторали (Буколики): Романтическое описание идеальной, беззаботной жизни пастухов и пастушек на лоне чистой природы (стиль рококо, сентиментализм) было создано греческим поэтом Теокритом и развито Вергилием в его «Буколиках».$$),
  (996, $$Образ поэта-изгнанника: Романтический миф о поэте, преследуемом жестокой властью и страдающем в глуши («Цыганы» Пушкина, стихи Лермонтова), начался с реальной трагедии Овидиана, который был сослан императором Августом на окраину империи в город Томы, где написал свои пронзительные «Скорбные элегии».$$),
  (997, $$Психология ревности: Первое детальное клиническое описание психосоматических симптомов ревности (жар, звон в ушах, бледность, потеря дара речи) дано в поэзии Сапфо, чьи строчки позже дословно переводил Катулл.$$),
  (998, $$Литературный культ Дружбы: Концепция того, что верный друг — это «половина твоей собственной души», развилась из трактата Цицерона «О дружбе» (Laelius de amicitia), который стал кодексом чести для европейского дворянства.$$),
  (999, $$Базовые ролевые модели: Первой детской приключенческой книгой, воспитывающей в мальчиках отвагу, смекалку и верность дому, на протяжении 2000 лет являлась «Одиссея» Гомера, которая была обязательным элементом античной школы (пайдейи).$$),
  (1000, $$Жанр мифологического пересказа: Вся детская литература о богах и героях (например, «Мифы Древней Греции» Николая Куна) базируется на «Мифологической библиотеке» Псевдо-Аполлодора (II в. до н.э.) — первом в истории успешном опыте систематизации и адаптации сложных религиозных текстов в доступные рассказы.$$),
  (1001, $$Концепция воспитания гражданина: Педагогические идеи Жан-Жака Руссо («Эмиль, или О воспитании») и Льва Толстого во многом вдохновлены трудами Плутарха, в частности его биографией спартанского законодателя Ликурга, где описана система коллективного воспитания детей.$$),
  (1002, $$Жанр басенного поучения: Использование коротких историй про животных с явной «моралью» в конце для воспитания маленьких детей — метод, научно обоснованный Квинтилианом в его педагогических трактатах, где он рекомендовал заучивать басни Эзопа для развития речи и этики.$$),
  (1003, $$Развитие памяти через стихи: Современная школьная практика заучивания стихов наизусть для развития памяти и когнитивных способностей ребенка зародилась в греческих школах грамматиков, где ученики были обязаны знать тысячи строк из Гомера на память.$$),
  (1004, $$Школьные хрестоматии: Формат учебника-хрестоматии (сборника лучших отрывков из разных авторов для учебного чтения) был придуман в Александрии для обучения детей риторике и грамматике.$$),
  (1005, $$Идея игрового обучения: Мысль о том, что обучение детей начальных классов должно проходить в игровой, ненасильственной форме, впервые детально обосновал Платон в VII книге трактата «Законы».$$),
  (1006, $$Образ доброго наставника: Хрестоматийный литературный образ мудрого, любящего учителя, который не наказывает, а ведет к истине беседой (прообраз Альбуса Дамблдора или магистра Йоды), списан с образа Сократа, созданного Ксенофонтом в его «Воспоминаниях о Сократе».$$),
  (1007, $$Жанр сказочной метаморфозы: Детские сказки о превращении людей в животных или предметы (Пиноккио, Чудесное путешествие Нильса) используют литературные механизмы, разработанные Овидием в «Метаморфозах», где превращение всегда служит отражением внутренней сути героя.$$),
  (1008, $$Понятие Школы: Само слово «школа» происходит от древнегреческого Schole, которое в античной литературе (в частности, у Платона) означало «досуг», «свободное время, посвященное мудрым беседам и саморазвитию».$$),
  (1009, $$«Евгений Онегин» Пушкина: Пушкин сознательно строил образ Татьяны Лариной и её внутренний мир на основе чтения французских переводов элегий Проперция и поэм Овидия, о чем он прямо упоминает в романе («И между тем читал Овидия...»).$$),
  (1010, $$«Мастер и Маргарита» Булгакова: Образ Понтия Пилата и атмосфера Ершалаима в романе Булгакова списаны не только с Евангелий, но и с исторических трудов римского историка Тацита и книги Иосифа Флавия «Иудейская война».$$),
  (1011, $$«Мертвые души» Гоголя: Гоголь изначально задумывал свою поэму по структуре «Божественной комедии» Данте, которая, в свою очередь, является точной копией VI книги «Энеиды» Вергилия, описывающей схождение героя в подземный мир Тартар для встречи с тенями прошлого. Чичиков должен был пройти «Ад» (1-й том), «Чистилище» (уничтоженный 2-й том) и «Рай» (3-й том).$$),
  (1012, $$Философия Льва Толстого: Концепция Толстого о непротивлении злу насилием и его критика цивилизации во многом опираются на чтение трактатов Сенеки и философов-киников, чьи тексты Толстой переводил и издавал для крестьян в своем издательстве «Посредник».$$),
  (1013, $$«История одного города» Салтыкова-Щедрина: Великая русская сатира построена как прямая пародия на «Жизнь двенадцати цезарей» Светония. Описание безумств глуповских градоначальников — это зеркальное отражение светониевских биографий Калигулы и Нерона.$$),
  (1014, $$«Бедная Лиза» Карамзина: Родоначальник русского сентиментализма создал повесть под глубоким влиянием греческого пасторального романа Лонга «Дафнис и Хлоя», перенеся античную чистоту чувств пастушков в реалии подмосковного Симонова монастыря.$$),
  (1015, $$Поэзия Серебряного века: Культ античности был основой течения акмеизма (Николай Гумилев, Осип Мандельштам, Анна Ахматова). Мандельштам называл свою поэзию «тоской по мировой культуре», а его сборник «Tristia» назван в честь «Скорбных элегий» Овидия.$$),
  (1016, $$Драматургия Чехова: Пьесы Антон Чехова («Чайка», «Три сестры») с их атмосферой неминуемого рока, висящего над будничной жизнью героев, подсознательно используют структуру древнегреческой трагедии рока, где герои много разговаривают, но не могут изменить предначертанный финал.$$),
  (1017, $$«Отцы и дети» Тургенева: Образ нигилиста Базарова и его жесткий материализм — это литературная рецепция Тургеневым философии римского поэта-материалиста Лукреция Кара, который в поэме «О природе вещей» доказывал, что души нет, а весь мир — это лишь движение атомов в пустоте.$$),
  (1018, $$«Идиот» Достоевского: Создавая образ «положительно прекрасного человека» князя Мышкина, Достоевский ориентировался на образ Христа, но в литературном плане опирался на образы сократических диалогов Платона, где Сократ выглядит чудаком и глупцом для обывателей, но является носителем высшей мудрости.$$),
  (1019, $$Формирование иммунитета к пропаганде: Человек, прочитавший исторические труды Фукидида («История Пелопоннесской войны»), видит насквозь любые современные геополитические лозунги, так как Фукидид детально описал, как политики используют страх и патриотизм для развязывания несправедливых войн.$$),
  (1020, $$Развитие языковой автономии: Античная литература заставляет мозг работать со сложными синтаксическими периодами. Люди, читающие Цицерона или Ливия в хороших переводах, приобретают сложную, структурированную речь, защищенную от упрощения и цифрового сленга.$$),
  (1021, $$Психологический щит Стоиков: Чтение «Писем к Луцилию» Сенеки признано учеными лучшим немедикаментозным средством для обретения душевной стойкости в эпохи перемен и кризисов. Она учит отделять зоны своего контроля от внешних обстоятельств.$$),
  (1022, $$Понимание человеческой природы: Великие трагедии Софокла и Еврипида доказывают, что за 2500 лет природа человека (ревность, амбиции, любовь, предательство) не изменилась ни на йоту. Это знание лишает иллюзий и дает глубокую жизненную мудрость.$$),
  (1023, $$Эстетический суверенитет: Знакомство с высокой поэзией Горация и Вергилия формирует эталонный художественный вкус. Человеку, воспитавшему свой разум на античной гармонии, становится физически неинтересен низкокачественный культурный фастфуд.$$),
  (1024, $$Развитие иронии и скепсиса: Сатиры Лукиана Самосатского учат легкому, здоровому цинизму и скепсису по отношению к любым фанатичным культам, суевериям и псевдонаучным теориям.$$),
  (1025, $$Масштаб мышления: Античный эпос приучает мыслить категориями вечности, государств и поколений, что поднимает человека над мелкой повседневной суетой и бытовыми дрязгами.$$),
  (1026, $$Обретение личных этических опор: Диалоги Сократа ставят человека перед необходимостью лично ответить себе на вопросы: «Что есть справедливость?» и «Как прожить жизнь честно?», формируя несгибаемый внутренний моральный стержень.$$),
  (1027, $$Литературная эрудиция как маркер статуса: Знание античных сюжетов и авторов — это до сих пор высший код интеллектуальной элиты во всем мире, открывающий двери в высокоранговые культурные и научные сообщества.$$),
  (1028, $$Проживание тысячи жизней: Читая античную библиотеку, вы буквально забираете себе 1000-летний опыт умнейших людей человечества, получая колоссальное эволюционное преимущество в развитии собственного разума.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Keep the existing editorial pause for Russia-, Russian-, USSR-, and
-- Soviet-related cards reversible: records remain stored but not delivered.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';

